        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱（歷Fa-IV-1）戰後臺灣經濟轉型脈絡：\n1. 1950 年代：1953 年實施「耕者有其田」（徵收地主超額出租耕地轉放佃農，地主獲補償四大公司股票與實物土地債券），並採「進口替代」以國內生產取代進口民生品。\n2. 1960 年代：國內市場飽和，1966 年高雄「加工出口區」落成，轉向勞力密集「出口導向」工業。\n3. 1970 年代：1973 年第一次石油危機衝擊全球，政府推動「十大建設」（6 項交通、3 項重化工業、1 項核能發電），帶動重化工業基礎。",
