        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱（歷Na-IV-2、歷1b-IV-1）制度名稱與實際運作的史學判準：\n1. 汲取凱撒遇刺教訓：屋大維養父凱撒因公開擔任「終身獨裁官」觸怒懷念共和傳統的元老院貴族而遇刺身亡；屋大維遂採取外披「共和外衣」、內行「軍事獨裁集權」的巧妙策略。\n2. 政體實質判準：共和制的核心在於「權力分散制衡且最高執政者有任期限制」；當最高軍政大權永久集中於一人（且死後傳位繼承人提比略）時，實質上已由共和政體轉變為「君主帝制（羅馬帝國）」。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 分析題幹核心提問「為何保留共和官職仍被界定為羅馬帝國開端？」➔ 因為歷史學判斷政治體制看的是「實質權力歸屬與制衡機制是否存續」，而非表面招牌。\n2. 屋大維集大元帥、終身護民官、首席元老於一身，元老院失去制衡實權，標誌羅馬共和名存實亡、帝制正式確立。\n3. 核對四個選項，選項 (D) 精闢點出「名義與實質分離」的制度史判準。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• (A) 錯誤：屋大維恰恰是「保留元老院形式、刻意避免自稱國王或法老」，且羅馬帝國首都仍在羅馬城（四世紀君士坦丁才另建新都君士坦丁堡）。\n• (B) 錯誤：東征滅波斯帝國的是西元前四世紀馬其頓的「亞歷山大大帝」，而非羅馬的凱撒，且羅馬並未實行雅典的陶片放逐法。\n• (C) 錯誤：西元前 27 年耶穌尚未誕生！頒布《米蘭敕令》承認基督教合法是三百多年後（西元 313 年）的君士坦丁大帝，定為國教更是西元 392 年的狄奧多西大帝。",
