        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱（歷Ca-IV-2）清領後期開港通商之深遠影響：\n1. 開港背景：1858～1860 英法聯軍《天津條約》、《北京條約》開放淡水、安平、基隆、打狗四港。\n2. 空間重心轉移：清領前期臺灣呈「南重北輕」（一府二鹿三艋舺，糖米集中中南部）；開港後，高經濟價值的「茶葉（占出口總值逾半）」與「樟腦」皆產於中北部丘陵山地，帶動大稻埕與淡水、基隆港繁榮，北部關稅超越南部，配合沈葆楨增設臺北府、劉銘傳建省以臺北為省會，完成「政經重心由南向北移轉」。",
