        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱（地Aa-IV-1）經緯度氣候帶與時區計算公式：\n1. 緯度與氣候帶：北回歸線為 23.5°N、北極圈為 66.5°N，25°N 與 37°N 皆介於 23.5°N～66.5°N 之間，同屬「北半球中緯度溫帶」；緯度數值愈大，緯線圓圈愈短。\n2. 跨東西經時差公式：一地東經（120°E）、一地西經（120°W），經度差 ＝ 120° ＋ 120° ＝ 240°；時差 ＝ 240° ÷ 15° ＝ 16 小時（即 UTC+8 與 UTC-8 相差 16 小時），西經時間比東經「慢（晚）16 小時」。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 先將起飛時間換算為矽谷當地時間：11 月 10 日 22:00 往西減 16 小時 ➔ 22 － 16 ＝ 6，即起飛瞬間矽谷當地為「11 月 10 日清晨 06:00」。\n2. 再加上飛機飛行耗時 11 小時：11 月 10 日 06:00 ＋ 11 小時 ＝「11 月 10 日 17:00（下午 5 點）」。\n3. 核對地理特徵：25°N 與 37°N 皆在北半球中緯度溫帶，故選項 (D) 位置與抵達時間完全正確。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• (A) 錯誤：緯度愈高緯線愈短！矽谷（37°N）比桃園（25°N）更靠近北極，所在緯線周長比桃園「更短」；且 11 月 11 日 09:00 是漏算了 16 小時時差（只算臺灣時間）。\n• (B) 錯誤：37°N 的「N」代表北緯（北半球），季節與臺灣相同（皆為秋冬季），並非南半球。\n• (C) 錯誤：把「120°E（東經）」與「120°W（西經）」看成同一條經線誤以為相減為 0 度！一東一西跨過本初子午線必須「相加（120＋120＝240°）」。",
