        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱（地Aa-IV-1）大小比例尺黃金對比法則：\n1. 分數比大小：`1/5,000 ＞ 1/400,000`，分母愈小，分數值愈大！故【乙（1:5,000）】為「大比例尺」，【甲（1:400,000）】為「小比例尺」。\n2. 固定圖幅下：大比例尺＝縮小程度小＝涵蓋實際範圍「小」＝地物內容「詳細」＝同一地物在圖上面積「大」。",
