        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱（地Aa-IV-1）方位旋轉與面積比例換算：\n1. 方位十字旋轉法則：順時針依序為「北（N）→ 東（E）→ 南（S）→ 西（W）」。當北方（N）指向圖面「正右方」時，順時針轉 90° 圖面「正下方」為東方（E）、圖面「正左方」為南方（S）、圖面「正上方」則為「西方（W）」！\n2. 面積安全算法：永遠「先把圖上長、寬各自換算出實際公尺，最後再把實際長 × 實際寬」，最不容易少乘一次比例尺！",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 判定實際方位：北方在右 ➔ 左方為南、下方為東、上方為「正西方」。操場在教學大樓圖面正上方，故實際位於教學大樓的「正西方」（排除 A、D）。\n2. 計算實際長與寬（比例尺 1:2,000 代表圖上 1 cm ＝ 實地 2,000 cm ＝ 20 公尺）：\n   • 實際長 ＝ 5 cm × 20 m/cm ＝ 100 公尺；\n   • 實際寬 ＝ 3 cm × 20 m/cm ＝ 60 公尺。\n3. 計算實際面積：100 公尺 × 60 公尺 ＝「60,000 平方公尺」。\n4. 驗算無誤，正確答案為選項 (C)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• (A) 錯誤：忽略右上角旋轉過的方向標，盲目套用「上北下南」誤判為正北方，且面積算錯。\n• (B) 錯誤：方位判對正西方，但面積計算時誤用「圖上面積 15 cm² × 2,000 ＝ 30,000 cm²」或少算一個零變成 6,000 m²！\n• (D) 錯誤：順逆時針轉錯把上方當成東方（N 順時針 90° 是 E 在下方，上方必為 W），且面積僅乘一次比例尺。",
