      "badge": "會考空間環境整合 · 海岸地形與產業利用",
      "stem": "某地理實察社團利用暑假環島考察臺灣四段截然不同的海岸景觀，並寫下四則田野紀錄：\n• 【路段一】：海岸線平直且海水極淺，退潮時露出寬達數公里的泥質灘地，外海有一道道沙洲圍成平靜的潟湖，漁民在潟湖內搭建整齊的蚵棚養殖牡蠣。\n• 【路段二】：高聳陡峭的大理岩山壁直接插入深邃的太平洋，公路緊貼在懸崖半山腰開鑿，海面下地形陡降，常有賞鯨船出海觀察鯨豚。\n• 【路段三】：山脈餘脈伸入海中，受海浪長期侵蝕差別風化，形成海灣與突出的岬角相間，不僅擁有女王頭、燭臺石等奇岩，更有水深灣闊的國際商港。\n• 【路段四】：陽光熾熱、海水清澈溫暖，岸邊遍布由海洋生物骨骼堆積隆起並經海浪侵蝕的灰白色多孔礁岩，是著名的熱帶浮潛勝地。\n請問【路段一】至【路段四】依序對應臺灣哪四個方位的海岸？",
