        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱（地Ac-IV-4）自然危害與災害風險判準：\n1. 災害風險方程式：災害風險 ＝ 自然危害（如豪雨、地震） × 暴露度（危險區內的人口、房屋、財產數量） × 脆弱度（水土保持不良、建築防救災能力不足）。\n2. 坡地水土保持：原始天然闊葉針葉林根系深廣，能抓緊土壤並涵養水分；若濫墾改種淺根經濟作物（檳榔、茶樹、高麗菜），土壤失去抓地力，遇豪雨飽水後極易順陡坡與溪谷宣洩成土石流；而將住宅建於山谷溪流出口（沖積扇扇頂危險區）更大幅提高暴露度。",
