        "requiredKnowledge": "非洲有「高原大陸」與「熱帶大陸」之稱（赤道橫貫中部，南北回歸線分居南北，約四分之三面積在熱帶），東非板塊張裂形成世界最長「東非大裂谷」。氣候以赤道為軸呈「南北對稱」：(1) 熱帶雨林（0°～10°，赤道低壓終年上升對流雨，剛果盆地與幾內亞灣沿岸，幾內亞灣種植可可豆占全球逾六成）；(2) 熱帶莽原（10°～20°，夏濕季高草茂盛、冬乾季草木枯黃，促成東非野生動物逐水草南北大遷徙）；(3) 熱帶沙漠（20°～30°，回歸線副熱帶高壓下沉氣流籠罩，北有世界最大撒哈拉沙漠、西南有納米比與喀拉哈里沙漠）；(4) 溫帶地中海型（南北端 30°～35°，南非開普敦 1 月夏季乾熱、7 月冬季溫濕！）。十九世紀末歐洲列強柏林會議瓜分非洲，直接依經緯線劃定「人為直線國界」強行拆散或合併不同部族，並強推「單一農礦出口經濟」，獨立後易引發部族內戰與國際原物料跌價破產風險。",
        "sop": "第 1 步看非洲氣候先找「赤道（通過幾內亞灣內側與維多利亞湖）」上下對稱推演➔ 第 2 步注意東非赤道附近因「高原海拔高氣溫降」未成雨林而形成「熱帶莽原」！➔ 第 3 步南非開普敦在「南半球地中海型」，故 7 月是冬季多雨、1 月是夏季少雨（氣候圖波谷在 7 月、雨峰也在 7 月）！"
