        "【第 1 步：審題定位 · 題眼與已知】鎖定題幹控制變因與關鍵差異：\n• 相同條件：甲地（剛果盆地）與乙地（東非高原）皆位於「赤道（0° 緯線）」上（緯度相同！）；\n• 差異條件：甲地「海拔低平」呈現終年多雨「熱帶雨林」；乙地「海拔高達 1,500～2,000 公尺」呈現疏林高草與乾濕季動物遷徙之「熱帶莽原」。求造成同緯度氣候分異的主因。",
        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱（地Bg-IV-2）非洲氣候分布與東非高原特例原理：\n1. 赤道標準氣候：赤道地區理論上因太陽直射強烈、氣溫極高，空氣劇烈受熱膨脹上升（赤道低壓帶），終年盛行旺盛對流雨，形成「熱帶雨林氣候」（如西側低平的剛果盆地）。\n2. 地形海拔改變氣溫與對流：東非地區雖同處赤道，但因板塊張裂隆起形成高聳的「東非高原」，海拔上升使氣溫下降約 9～12°C，地表熱力不足以維持終年強烈的上升對流，僅在間熱帶輻合區移經時降雨，出現明顯乾濕季，遂發育為「熱帶莽原氣候（疏林草原）」。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 確認兩地緯度皆為 0°，排除緯度差異。\n2. 比對海拔高度：低平盆地（高溫強對流＝雨林）vs. 1,500～2,000m 高原（降溫弱對流＝莽原）。\n3. 核對四個選項，選項 (A) 精準闡明海拔地形降低氣溫、減弱對流作用，使東非赤道由熱帶雨林轉為熱帶莽原的科學機制。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• (B) 錯誤：副熱帶高氣壓籠罩在南北緯 20°～30° 回歸線附近（撒哈拉與喀拉哈里沙漠），並非 0° 赤道；且百萬牛羚斑馬遷徙吃草的是「熱帶莽原」而非寸草不生的沙漠！\n• (C) 錯誤：剛果盆地外海為幾內亞灣暖流而非歐洲的北大西洋暖流，且赤道東非緊鄰印度洋，並非溫帶大陸性氣候。\n• (D) 錯誤：地中海型氣候位於非洲最北端與最南端（緯度 30°～35°），赤道高原絕無寒帶針葉林轉地中海型之事。",
