        "【第 1 步：審題定位 · 題眼與已知】拆解題幹指出的兩大非洲人文地理痛點：\n特徵一（經濟脆弱性）：外匯高度依賴單一熱帶經濟作物（可可豆）與原礦出口，糧食與工業品卻需仰賴進口（「殖民式單一經濟」）；\n特徵二（政治邊界衝突）：國界呈筆直經緯線，切割傳統部族分布區。求共同歷史成因。",
        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱（地Bg-IV-2、歷Qc-IV-2）新帝國主義瓜分非洲之空間遺緒：\n1. 單一經濟（Monoculture Economy）：十九世紀末歐洲工業強國將非洲納為原料供應地，霸占肥沃耕地大規模種植母國需要的經濟作物（如幾內亞灣可可、東非咖啡茶葉、埃及棉花）或開採鑽石銅礦，排擠本土糧食生產；獨立後一旦國際可可或礦產價格暴跌，國家財政立即崩潰。\n2. 人為直線國界：1884～1885 年歐洲列強召開「柏林會議」在談判桌上直接拿地圖按經緯線瓜分非洲內陸，完全忽視當地數百個原住部族的傳統生活領域，埋下戰後非洲獨立國家頻繁爆發族群內戰與邊界衝突的禍根。",
