        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱（地Cb-IV-2）永續發展（Sustainable Development）與 SDGs 判準：\n1. 定義：「滿足當代人的需求，同時不損及後代子孫滿足其自身需求之發展」。\n2. 三大支柱平衡：永續並非單一環保至上或單一GDP至上，而是必須同時兼顧「環境保護（Environmental）、經濟成長（Economic）、社會包容與公平正義（Social）」三者的動態平衡，並透過公開審議納入不同利害關係人聲音。",
