        "requiredKnowledge": "(1) 坡度陡緩：同一張等高線圖等高距固定時，等高線愈「密集」代表水平距離短而高度落差大，坡度愈「陡峭」；等高線愈「稀疏」代表坡度愈「平緩」（登山省力安全路線應選稀疏處或沿山脊稜線）；(2) 閉合圈：內高外低為山頂／山峰，內低外高為盆地／窪地，兩山頂間低凹如馬鞍處為「鞍部」（常為山區越嶺古道隘口）；(3) 脊與谷：等高線向海拔「低處凸出」為中間高兩側低的「山脊（稜線／分水嶺）」；等高線向海拔「高處凸出（V字尖端指高處）」為中間低兩側高的「山谷（河谷）」，唯一能發育溪流之處！",
