        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 判讀【甲地】：內高（800m）外低（600m）＝山頂，非盆地，排除 (B)。\n2. 判讀【乙線段】與【丙線段】：乙尖端朝 700m 高處凸出＝山谷，發育溪流，且北高南低故溪水「由北向南流」；丙朝 200m 低處凸出＝山脊（分水嶺），排除 (A)，確認選項 (C) 正確。\n3. 判讀【丁村落】：位於大壩下游海拔 120m 處，排放污水往下游流走，不會倒流進入海拔 250m 的水庫內，故「不在水庫集水區範圍內」，排除 (D)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• (A) 錯誤：把「凸低為脊（丙）」與「凸高為谷（乙）」記反，且將水往低處流的流向顛倒。\n• (B) 錯誤：將內高外低的「山頂」誤認成外高內低的「盆地」。\n• (D) 錯誤：段考超愛考的集水區陷阱！丁村落雖然在同一條溪的「流域」內，但因為在大壩「下游」，不屬於水庫「集水區」，不會污染水庫水源。",
