        "requiredKnowledge": "(1) 早期東北部與五大湖重工業區：憑藉五大湖廉價水運將蘇必略湖「鐵礦」與阿帕拉契山「煤礦」匯聚，發展匹茲堡鋼鐵、底特律汽車等傳統製造業；二十世紀後期因工資高漲、設備老舊及日德亞洲進口競爭而工廠關門人口外流，被稱為「鐵鏽帶（Rust Belt）」；(2) 近年南移西移「陽光帶（Sun Belt）」：美國南部與西部緯度較低陽光充足氣候宜人、地價較合理且頂尖大學研究機構林立（如加州史丹佛、柏克萊大學），發展高附加價值之「資訊電子與AI軟體（加州矽谷）、航太科技（西雅圖、休士頓）、石化能源（墨西哥灣休士頓）與影視娛樂（洛杉磯好萊塢）」，紐約（華爾街金融、聯合國總部）則穩居全球金融樞紐。",
