        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱（地Bf-IV-1、地Bf-IV-3）中亞經濟與鹹海生態危機：\n1. 中亞溫帶沙漠日照長、採收期乾燥少雨，利於高品質白色棉絮吐絮採收，烏茲別克等國大量種植「棉花（白金）」。\n2. 內流河水平衡破壞：注入「鹹海（Aral Sea）」的水源完全仰賴發源於帕米爾與天山冰川的「阿姆河」與「錫爾河」；當兩河河水在半途被大量截流灌溉棉田，入湖水量遠低於湖面蒸發量，終釀成二十世紀最震撼的人為環境災難之一。",
