        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱（地Bf-IV-1）乾燥氣候傳統水資源調適智慧：\n1. 乾燥區最大敵人是「高溫強烈蒸發」與「風沙淤塞」：若在地面開挖露天明渠，珍貴的高山融雪水還沒流到幾十公里外的綠洲農田，就已經在 42°C 烈日下蒸發殆盡或被沙漠風沙填平。\n2. 坎兒井三大優勢：(a) 地下暗渠隔絕烈日，大幅減少水分蒸發；(b) 避免風沙吹入污染掩埋；(c) 順山麓沖積扇天然坡度由高處自流至低處綠洲，完全不需耗費電力或獸力抽水，符合低碳永續精神。",
