        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱（公Ad-IV-1）《憲法》基本權利分類精準邊界：\n1. **受益權**（請求國家提供積極作為或救濟利益）：(a) 經濟上受益權（生存權、工作權、財產權）；(b) 教育上受益權（受國民教育）；(c) **行政上受益權（請願權、訴願權）**；(d) 司法上受益權（訴訟權）。\n   • 區分請願 vs. 訴願：政策還沒做、向議會或行政機關提興革建議＝「**請願權**」；行政機關已經對你做出違法或不當行政處分（如開罰單），向原處分機關之上級機關請求撤銷變更＝「**訴願權**」！\n2. **參政權**（《憲法》第 17、18 條）：選舉、罷免、創制、複決，以及**應考試、服公職**！\n3. **受國民教育（第 21 條）**：唯一兼具「基本權利（教育受益權）」與「國民基本義務」雙重性質！",
